				},
			},
		},
		{
			name: "metadata from JSON",
			path: "./testdata/config/metadata.json",
			expected: func() *Config {
				cfg := Default()
				cfg.Metadata.CheckForUpdates = false
				return cfg
			}(),
		},
		{
			name:     "defaults after metadata override",
			path:     "./testdata/config/default.yml",
			expected: Default(),
		},
	}

	for _, tt := range tests {
		var (
			path     = tt.path
			wantErr  = tt.wantErr
			expected = tt.expected
